#include <stdio.h>

typedef struct {
    long long x, y;
} Point;

static long long cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

static long long dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

static Point subtract(Point a, Point b) {
    Point result = {a.x - b.x, a.y - b.y};
    return result;
}

static long long squared_length(Point a) {
    return dot(a, a);
}

int main(void) {
    Point p[7];

    for (int i = 0; i < 7; i++) {
        if (scanf("%lld %lld", &p[i].x, &p[i].y) != 2) {
            return 0;
        }
    }

    Point v12 = subtract(p[1], p[0]);
    Point v13 = subtract(p[2], p[0]);
    Point base = subtract(p[2], p[1]);

    int valid = dot(v12, v13) > 0
        && squared_length(v12) == squared_length(v13)
        && cross(base, subtract(p[3], p[1])) == 0
        && cross(base, subtract(p[4], p[1])) == 0
        && p[1].x + p[2].x == p[3].x + p[4].x
        && p[1].y + p[2].y == p[3].y + p[4].y
        && squared_length(base) > squared_length(subtract(p[4], p[3]))
        && dot(base, subtract(p[5], p[3])) == 0
        && dot(base, subtract(p[6], p[4])) == 0
        && squared_length(subtract(p[5], p[3])) == squared_length(subtract(p[6], p[4]));

    long long side1 = cross(base, subtract(p[0], p[1]));
    long long side6 = cross(base, subtract(p[5], p[1]));

    valid = valid && ((side1 < 0 && side6 > 0) || (side1 > 0 && side6 < 0));

    puts(valid ? "S" : "N");
    return 0;
}
